-- MySQL 8 (vehicle_db). Seed realistic rental-fleet data for vehicle-service.
--
-- !! DESTRUCTIVE: deletes ALL rows of vehicle_status_history, vehicle_images, vehicle_documents,
-- !! vehicles, vehicle_models and vehicle_categories, then inserts the data below.
-- Run only on a development database, after the latest vehicle-service has started once
-- (so Hibernate has created the tables and vehicle_models.category_id).
-- vehicle_images / vehicle_documents rows are removed; their files stay in MinIO as unreferenced
-- objects (clear the vehicle-images and vehicle-documents buckets in the MinIO console if you want).
-- The seeded vehicles have no photos: upload real photos in the admin UI (Chi tiet xe > Mo anh va giay to).
-- Data is fictional: VINs and plates are generated, dates are relative to the moment you run the script.
--
-- docker exec -i <mysql-container> mysql -uroot -p --default-character-set=utf8mb4 vehicle_db < seed_realistic_fleet.sql

SET NAMES utf8mb4;
START TRANSACTION;
SET FOREIGN_KEY_CHECKS = 0;
DELETE FROM vehicle_status_history;
DELETE FROM vehicle_images;
DELETE FROM vehicle_documents;
DELETE FROM vehicles;
DELETE FROM vehicle_models;
DELETE FROM vehicle_categories;
SET FOREIGN_KEY_CHECKS = 1;

-- Loai xe

-- Mau xe

-- Xe

-- Lich su doi trang thai

COMMIT;

-- Kiem tra nhanh
SELECT status, COUNT(*) AS xe FROM vehicles WHERE is_deleted = 0 GROUP BY status;
SELECT c.name AS loai_xe, COUNT(v.id) AS xe FROM vehicle_categories c LEFT JOIN vehicles v ON v.category_id = c.id AND v.is_deleted = 0 GROUP BY c.name;
